CREATE OR REPLACE PROCEDURE sp(para_Year_Join integer, para_Country text, para_Artist_ID integer, para_Exhibition_ID integer, para_integer text)
LANGUAGE plpgsql
AS $$
BEGIN
IF para_Year_Join > para_Artist_ID THEN
 UPDATE "artist" SET "Country" = 'A';
 DELETE FROM "artist" WHERE "Year_Join" = 1;
 UPDATE "artist" SET "Country" = 'B';
