 DELETE FROM "exhibition_record" WHERE "Exhibition_ID" = 2;
 UPDATE "exhibition_record" SET "Attendance" = "Attendance" + 1;
 DELETE FROM "exhibition_record" WHERE "Exhibition_ID" = 3;
