 DELETE FROM "artist" WHERE "Year_Join" = para_Year_Join;
 UPDATE "exhibition_record" SET "Attendance" = "Attendance" + 1;
 DELETE FROM "exhibition_record" WHERE "Exhibition_ID" = para_Exhibition_ID;
 UPDATE "artist" SET "Country" = 'phase2_A';
 DELETE FROM "artist" WHERE "Year_Join" = 101;
 UPDATE "artist" SET "Country" = 'phase2_B';
 DELETE FROM "artist" WHERE "Year_Join" = 102;
 UPDATE "exhibition_record" SET "Attendance" = "Attendance" + 1;
 DELETE FROM "exhibition_record" WHERE "Exhibition_ID" = 101;
 UPDATE "exhibition_record" SET "Attendance" = "Attendance" + 1;
 DELETE FROM "exhibition_record" WHERE "Exhibition_ID" = 102;
 UPDATE "artist" SET "Country" = 'phase2_C';
 DELETE FROM "artist" WHERE "Year_Join" = 103;
 UPDATE "exhibition_record" SET "Attendance" = "Attendance" + 1;
 DELETE FROM "exhibition_record" WHERE "Exhibition_ID" = 103;
 UPDATE "artist" SET "Country" = 'complete' WHERE "Year_Join" = 999;
 UPDATE "exhibition_record" SET "integer" = 'complete_log' WHERE "Exhibition_ID" = 999;
